"use client"

import type { FormEvent } from "react"
import { useMemo, useState, useTransition } from "react"
import { useRouter } from "next/navigation"
import { AlertTriangle, CheckCircle2, Loader2, LockKeyhole } from "lucide-react"

import { settlePayrollEmployeeBalanceCaseAction } from "@/actions/payroll/payroll-control.actions"

type SettlementMethod = "CASH" | "BANK_TRANSFER" | "MOBILE_MONEY" | "PAYROLL_DEDUCTION"

type Props = {
  balanceCaseId: string
  caseNumber: string
  employeeId: string
  outstandingAmount: string
  currency: string
  disabled?: boolean
}

type FormNotice =
  | { kind: "success"; message: string }
  | { kind: "fresh-auth" | "error"; message: string; correlationId?: string }

const settlementMethods: Array<{ value: SettlementMethod; label: string }> = [
  { value: "CASH", label: "Cash" },
  { value: "BANK_TRANSFER", label: "Bank" },
  { value: "MOBILE_MONEY", label: "Mobile" },
  { value: "PAYROLL_DEDUCTION", label: "Deduction" },
]

function todayInputValue() {
  return new Date().toISOString().slice(0, 10)
}

function numericDefault(value: string) {
  return /^\d+(\.\d{1,2})?$/.test(value) ? value : ""
}

function nextIdempotencyKey(balanceCaseId: string) {
  const random = globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random().toString(36).slice(2)}`
  return `payroll-balance-settlement:${balanceCaseId}:${random}`
}

export default function PayrollEmployeeBalanceSettlementForm({
  balanceCaseId,
  caseNumber,
  employeeId,
  outstandingAmount,
  currency,
  disabled = false,
}: Props) {
  const router = useRouter()
  const defaultAmount = useMemo(() => numericDefault(outstandingAmount), [outstandingAmount])
  const [settledById, setSettledById] = useState(employeeId)
  const [settlementDate, setSettlementDate] = useState(todayInputValue)
  const [settlementMethod, setSettlementMethod] = useState<SettlementMethod>("CASH")
  const [amount, setAmount] = useState(defaultAmount)
  const [settlementEvidenceHash, setSettlementEvidenceHash] = useState("")
  const [documentHash, setDocumentHash] = useState("")
  const [reference, setReference] = useState("")
  const [notes, setNotes] = useState("")
  const [idempotencyKey, setIdempotencyKey] = useState(() => nextIdempotencyKey(balanceCaseId))
  const [notice, setNotice] = useState<FormNotice | null>(null)
  const [isPending, startTransition] = useTransition()

  function submitSettlement(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    setNotice(null)

    const payload = {
      balanceCaseId,
      settledById: settledById.trim(),
      settlementDate,
      settlementMethod,
      amount: amount.trim(),
      settlementEvidenceHash: settlementEvidenceHash.trim(),
      ...(documentHash.trim() ? { documentHash: documentHash.trim() } : {}),
      ...(reference.trim() ? { reference: reference.trim() } : {}),
      ...(notes.trim() ? { notes: notes.trim() } : {}),
      idempotencyKey,
      metadata: {
        sourceSurface: "/dashboard/payroll/payments",
        caseNumber,
      },
    }

    startTransition(async () => {
      const response = await settlePayrollEmployeeBalanceCaseAction(payload)
      if (response.success) {
        setNotice({
          kind: "success",
          message: response.data.idempotent
            ? "Settlement evidence was already recorded for this request."
            : "Settlement evidence recorded.",
        })
        setIdempotencyKey(nextIdempotencyKey(balanceCaseId))
        setSettlementEvidenceHash("")
        setDocumentHash("")
        setReference("")
        setNotes("")
        router.refresh()
        return
      }

      setNotice({
        kind: response.code === "FRESH_AUTH_REQUIRED" ? "fresh-auth" : "error",
        message: response.error || "Settlement evidence could not be recorded.",
        correlationId: response.correlationId,
      })
    })
  }

  return (
    <form onSubmit={submitSettlement} className="mt-3 grid gap-2 rounded-lg border border-white/10 bg-white/[0.04] p-3">
      <div className="flex items-center gap-2 text-xs font-semibold uppercase tracking-normal text-slate-400">
        <LockKeyhole className="h-3.5 w-3.5 text-cyan-200" aria-hidden="true" />
        <span>Fresh-auth settlement</span>
      </div>

      <div className="grid gap-2 sm:grid-cols-2">
        <label className="grid gap-1 text-xs text-slate-400">
          <span>Settlement amount</span>
          <input
            value={amount}
            onChange={(event) => setAmount(event.target.value)}
            required
            inputMode="decimal"
            placeholder={currency}
            disabled={disabled || isPending}
            className="min-h-9 rounded-md border border-white/10 bg-slate-950/60 px-2 text-sm text-white outline-none focus:border-cyan-300/60 disabled:opacity-60"
          />
        </label>
        <label className="grid gap-1 text-xs text-slate-400">
          <span>Settlement date</span>
          <input
            type="date"
            value={settlementDate}
            onChange={(event) => setSettlementDate(event.target.value)}
            required
            disabled={disabled || isPending}
            className="min-h-9 rounded-md border border-white/10 bg-slate-950/60 px-2 text-sm text-white outline-none focus:border-cyan-300/60 disabled:opacity-60"
          />
        </label>
      </div>

      <div className="grid gap-2 sm:grid-cols-2">
        <label className="grid gap-1 text-xs text-slate-400">
          <span>Method</span>
          <select
            value={settlementMethod}
            onChange={(event) => setSettlementMethod(event.target.value as SettlementMethod)}
            disabled={disabled || isPending}
            className="min-h-9 rounded-md border border-white/10 bg-slate-950/60 px-2 text-sm text-white outline-none focus:border-cyan-300/60 disabled:opacity-60"
          >
            {settlementMethods.map((method) => (
              <option key={method.value} value={method.value}>{method.label}</option>
            ))}
          </select>
        </label>
        <label className="grid gap-1 text-xs text-slate-400">
          <span>Settled by ID</span>
          <input
            value={settledById}
            onChange={(event) => setSettledById(event.target.value)}
            required
            disabled={disabled || isPending}
            className="min-h-9 rounded-md border border-white/10 bg-slate-950/60 px-2 text-sm text-white outline-none focus:border-cyan-300/60 disabled:opacity-60"
          />
        </label>
      </div>

      <label className="grid gap-1 text-xs text-slate-400">
        <span>Evidence hash</span>
        <input
          value={settlementEvidenceHash}
          onChange={(event) => setSettlementEvidenceHash(event.target.value)}
          required
          placeholder="sha256:..."
          disabled={disabled || isPending}
          className="min-h-9 rounded-md border border-white/10 bg-slate-950/60 px-2 text-sm text-white outline-none focus:border-cyan-300/60 disabled:opacity-60"
        />
      </label>

      <div className="grid gap-2 sm:grid-cols-2">
        <label className="grid gap-1 text-xs text-slate-400">
          <span>Document hash</span>
          <input
            value={documentHash}
            onChange={(event) => setDocumentHash(event.target.value)}
            placeholder="optional"
            disabled={disabled || isPending}
            className="min-h-9 rounded-md border border-white/10 bg-slate-950/60 px-2 text-sm text-white outline-none focus:border-cyan-300/60 disabled:opacity-60"
          />
        </label>
        <label className="grid gap-1 text-xs text-slate-400">
          <span>Reference</span>
          <input
            value={reference}
            onChange={(event) => setReference(event.target.value)}
            placeholder="optional"
            maxLength={200}
            disabled={disabled || isPending}
            className="min-h-9 rounded-md border border-white/10 bg-slate-950/60 px-2 text-sm text-white outline-none focus:border-cyan-300/60 disabled:opacity-60"
          />
        </label>
      </div>

      <label className="grid gap-1 text-xs text-slate-400">
        <span>Notes</span>
        <textarea
          value={notes}
          onChange={(event) => setNotes(event.target.value)}
          maxLength={2000}
          rows={2}
          disabled={disabled || isPending}
          className="min-h-16 resize-y rounded-md border border-white/10 bg-slate-950/60 px-2 py-2 text-sm text-white outline-none focus:border-cyan-300/60 disabled:opacity-60"
        />
      </label>

      <p className="break-all text-[11px] text-slate-500">{idempotencyKey}</p>

      {notice ? (
        <div className={`flex items-start gap-2 rounded-md border px-3 py-2 text-xs ${notice.kind === "success" ? "border-emerald-400/30 bg-emerald-400/10 text-emerald-100" : "border-amber-400/30 bg-amber-400/10 text-amber-100"}`}>
          {notice.kind === "success" ? <CheckCircle2 className="mt-0.5 h-3.5 w-3.5 shrink-0" aria-hidden="true" /> : <AlertTriangle className="mt-0.5 h-3.5 w-3.5 shrink-0" aria-hidden="true" />}
          <div className="min-w-0">
            <p className="break-words font-semibold">{notice.message}</p>
            {notice.kind !== "success" && notice.correlationId ? <p className="mt-1 break-all text-slate-400">{notice.correlationId}</p> : null}
          </div>
        </div>
      ) : null}

      <button
        type="submit"
        disabled={disabled || isPending}
        className="inline-flex min-h-9 items-center justify-center gap-2 rounded-md border border-cyan-300/30 bg-cyan-300/15 px-3 text-sm font-semibold text-cyan-50 transition hover:bg-cyan-300/20 disabled:cursor-not-allowed disabled:opacity-60"
      >
        {isPending ? <Loader2 className="h-4 w-4 animate-spin" aria-hidden="true" /> : <LockKeyhole className="h-4 w-4" aria-hidden="true" />}
        Record settlement
      </button>
    </form>
  )
}

"use client";

import type { FormEvent } from "react";
import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import {
  AlertTriangle,
  CheckCircle2,
  Loader2,
  LockKeyhole,
  Send,
} from "lucide-react";

import {
  enqueuePayrollAuthorityAdapterExecutionAction,
  type PayrollDeclarationWorkbenchResult,
} from "@/actions/payroll/payroll-control.actions";

type DeclarationRow = PayrollDeclarationWorkbenchResult["declarations"][number];
type ActionResponse = {
  success: boolean;
  data?: {
    idempotent?: boolean;
    execution?: {
      status?: string | null;
      correlationId?: string | null;
      authorityAdapterKey?: string | null;
      authorityAdapterProofHash?: string | null;
    } | null;
  } | null;
  error?: string | null;
  code?: string | null;
  correlationId?: string | null;
};
type Notice =
  | { kind: "success"; message: string; details?: string[] }
  | { kind: "fresh-auth" | "error"; message: string; correlationId?: string };

function nextKey(declarationId: string) {
  const random =
    globalThis.crypto?.randomUUID?.() ??
    `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  return `payroll-declaration:authority-adapter:${declarationId}:${random}`;
}

function Badge({ value }: { value: string | null | undefined }) {
  return (
    <span className="inline-flex min-h-7 max-w-full items-center rounded-md border border-white/10 bg-white/[0.06] px-2.5 py-1 text-xs font-semibold text-slate-100">
      <span className="truncate">{value ?? "Pending"}</span>
    </span>
  );
}

function noticeFromResponse(response: ActionResponse): Notice {
  if (response.success) {
    const execution = response.data?.execution ?? null;
    return {
      kind: "success",
      message: response.data?.idempotent
        ? "Authority adapter execution was already queued."
        : "Authority adapter execution queued.",
      details: [
        execution?.status ? `Status: ${execution.status}` : null,
        execution?.authorityAdapterKey
          ? `Adapter: ${execution.authorityAdapterKey}`
          : null,
        execution?.correlationId
          ? `Correlation: ${execution.correlationId}`
          : null,
        execution?.authorityAdapterProofHash
          ? `Proof: ${execution.authorityAdapterProofHash}`
          : null,
      ].filter((item): item is string => Boolean(item)),
    };
  }

  return {
    kind: response.code === "FRESH_AUTH_REQUIRED" ? "fresh-auth" : "error",
    message:
      response.error ||
      "Authority adapter execution could not be queued from this session.",
    correlationId: response.correlationId ?? undefined,
  };
}

function NoticePanel({ notice }: { notice: Notice | null }) {
  if (!notice) return null;
  const success = notice.kind === "success";

  return (
    <div
      className={`flex items-start gap-2 rounded-md border px-3 py-2 text-xs ${
        success
          ? "border-emerald-400/30 bg-emerald-400/10 text-emerald-100"
          : "border-amber-400/30 bg-amber-400/10 text-amber-100"
      }`}
    >
      {success ? (
        <CheckCircle2
          className="mt-0.5 h-3.5 w-3.5 shrink-0"
          aria-hidden="true"
        />
      ) : (
        <AlertTriangle
          className="mt-0.5 h-3.5 w-3.5 shrink-0"
          aria-hidden="true"
        />
      )}
      <div className="min-w-0">
        <p className="break-words font-semibold">{notice.message}</p>
        {success && notice.details?.length ? (
          <div className="mt-1 grid gap-1 text-slate-300">
            {notice.details.map((detail) => (
              <p key={detail} className="break-all">
                {detail}
              </p>
            ))}
          </div>
        ) : null}
        {!success && notice.correlationId ? (
          <p className="mt-1 break-all text-slate-400">
            {notice.correlationId}
          </p>
        ) : null}
      </div>
    </div>
  );
}

export default function PayrollDeclarationAuthorityExecutionPanel({
  declaration,
}: {
  declaration: DeclarationRow;
}) {
  const router = useRouter();
  const [isPending, startTransition] = useTransition();
  const [notice, setNotice] = useState<Notice | null>(null);
  const [idempotencyKey, setIdempotencyKey] = useState(() =>
    nextKey(declaration.id),
  );
  const gate = declaration.adapterExecution;

  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!gate.canEnqueue || !gate.declarationEvidenceId) return;
    setNotice(null);
    startTransition(async () => {
      const response = await enqueuePayrollAuthorityAdapterExecutionAction({
        declarationEvidenceId: gate.declarationEvidenceId,
        idempotencyKey,
      });
      const nextNotice = noticeFromResponse(response);
      setNotice(nextNotice);
      if (nextNotice.kind === "success") {
        setIdempotencyKey(nextKey(declaration.id));
        router.refresh();
      }
    });
  }

  return (
    <div className="mt-3 grid gap-2 rounded-md border border-cyan-300/20 bg-cyan-300/10 p-3 text-xs">
      <div className="flex items-center gap-2 font-semibold uppercase tracking-normal text-cyan-100">
        <LockKeyhole className="h-3.5 w-3.5" aria-hidden="true" />
        <span>Certified adapter enqueue</span>
      </div>
      <div className="flex flex-wrap gap-2">
        <Badge value={gate.requiredPermission} />
        {gate.requiresFreshAuth ? <Badge value="Fresh auth" /> : null}
        <Badge value={gate.status ?? (gate.canEnqueue ? "READY" : "BLOCKED")} />
      </div>
      <p className="break-words text-slate-300">{gate.reason}</p>
      {gate.queuedEvidenceId ||
      gate.correlationId ||
      gate.authorityAdapterKey ? (
        <div className="grid gap-1 rounded-md border border-white/10 bg-slate-950/30 p-2 text-slate-400">
          {gate.authorityAdapterKey ? (
            <p className="break-all">Adapter: {gate.authorityAdapterKey}</p>
          ) : null}
          {gate.queuedEvidenceId ? (
            <p className="break-all">Evidence: {gate.queuedEvidenceId}</p>
          ) : null}
          {gate.correlationId ? (
            <p className="break-all">Correlation: {gate.correlationId}</p>
          ) : null}
        </div>
      ) : null}
      {gate.canEnqueue ? (
        <form onSubmit={submit} className="grid gap-2">
          <div className="rounded-md border border-white/10 bg-white/[0.04] px-2 py-1.5 text-[11px] text-slate-500">
            <p className="font-semibold uppercase tracking-normal">
              Idempotency key
            </p>
            <p className="mt-1 break-all">{idempotencyKey}</p>
          </div>
          <NoticePanel notice={notice} />
          <button
            type="submit"
            disabled={isPending}
            aria-busy={isPending}
            className="inline-flex min-h-9 items-center justify-center gap-2 rounded-md border border-cyan-300/30 bg-cyan-300/15 px-3 text-sm font-semibold text-cyan-50 transition hover:bg-cyan-300/20 disabled:cursor-not-allowed disabled:opacity-60"
          >
            {isPending ? (
              <Loader2 className="h-4 w-4 animate-spin" aria-hidden="true" />
            ) : (
              <Send className="h-4 w-4" aria-hidden="true" />
            )}
            Queue adapter execution
          </button>
        </form>
      ) : (
        <NoticePanel notice={notice} />
      )}
    </div>
  );
}

